import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
const supabase = createClient(supabaseUrl, supabaseKey)

export type UserRole = 'admin' | 'scout' | 'analyst' | 'viewer'

export interface UserPermissions {
    role: UserRole
    can_scout: boolean
    can_view_analytics: boolean
    can_manage_data: boolean
    can_manage_users: boolean
}

const fallbackAdminEmails = (process.env.NEXT_PUBLIC_ADMIN_EMAILS || '')
    .split(',')
    .map(e => e.trim().toLowerCase())
    .filter(Boolean)

const isFallbackAdmin = (email: string | undefined): boolean => {
    if (!email) return false
    return fallbackAdminEmails.includes(email.toLowerCase())
}

export const isAdmin = async (email: string | undefined, userId?: string): Promise<boolean> => {
    if (!email) return false
    
    if (isFallbackAdmin(email)) return true
    
    if (userId) {
        const { data } = await supabase
            .from('user_roles')
            .select('role')
            .eq('user_id', userId)
            .eq('role', 'admin')
            .single()
        
        if (data) return true
    }
    
    return false
}

export const getUserRole = async (userId: string): Promise<UserPermissions | null> => {
    const { data: user } = await supabase
        .from('user_roles')
        .select('*')
        .eq('user_id', userId)
        .single()
    
    if (user) {
        return {
            role: user.role,
            can_scout: user.can_scout,
            can_view_analytics: user.can_view_analytics,
            can_manage_data: user.can_manage_data,
            can_manage_users: user.can_manage_users
        }
    }
    
    return null
}

export const getUserPermissions = async (email: string | undefined, userId?: string): Promise<UserPermissions> => {
    const defaultPermissions: UserPermissions = {
        role: 'viewer',
        can_scout: false,
        can_view_analytics: false,
        can_manage_data: false,
        can_manage_users: false
    }
    
    if (!email) return defaultPermissions
    
    if (isFallbackAdmin(email)) {
        return {
            role: 'admin',
            can_scout: true,
            can_view_analytics: true,
            can_manage_data: true,
            can_manage_users: true
        }
    }
    
    if (userId) {
        const permissions = await getUserRole(userId)
        if (permissions) return permissions
    }
    
    return defaultPermissions
}

export const setUserRole = async (
    adminUserId: string,
    targetEmail: string,
    role: UserRole,
    permissions: Omit<UserPermissions, 'role'>
): Promise<{ success: boolean; error?: string }> => {
    const { data: existingUser } = await supabase
        .from('user_roles')
        .select('user_id')
        .eq('email', targetEmail)
        .single()
    
    if (existingUser) {
        const { error } = await supabase
            .from('user_roles')
            .update({
                role,
                can_scout: permissions.can_scout,
                can_view_analytics: permissions.can_view_analytics,
                can_manage_data: permissions.can_manage_data,
                can_manage_users: permissions.can_manage_users,
                updated_at: new Date().toISOString()
            })
            .eq('email', targetEmail)
        
        if (error) return { success: false, error: error.message }
    } else {
        const { error } = await supabase
            .from('user_roles')
            .insert({
                email: targetEmail,
                role,
                can_scout: permissions.can_scout,
                can_view_analytics: permissions.can_view_analytics,
                can_manage_data: permissions.can_manage_data,
                can_manage_users: permissions.can_manage_users
            })
        
        if (error) return { success: false, error: error.message }
    }
    
    return { success: true }
}

export const removeUserRole = async (adminUserId: string, targetEmail: string): Promise<{ success: boolean; error?: string }> => {
    const { error } = await supabase
        .from('user_roles')
        .delete()
        .eq('email', targetEmail)
    
    if (error) return { success: false, error: error.message }
    return { success: true }
}

export const getAllUserRoles = async (): Promise<Array<UserPermissions & { email: string }>> => {
    const { data, error } = await supabase
        .from('user_roles')
        .select('*')
        .order('created_at', { ascending: false })
    
    if (error) return []
    
    return (data || []).map(u => ({
        email: u.email,
        role: u.role,
        can_scout: u.can_scout,
        can_view_analytics: u.can_view_analytics,
        can_manage_data: u.can_manage_data,
        can_manage_users: u.can_manage_users
    }))
}
